package handler

import "encoding/base64"

// Web assets modelled on a live, internet-facing Danfoss AK-SM "StoreView Web"
// refrigeration system manager. The favicon, logo and response headers below are
// captured verbatim from the real device; the landing page is a self-contained
// static login styled to match it.
//
// Why not the device's real index.html? StoreView is an Angular single-page app:
// its real landing document is an empty <app-root> plus hashed JS/CSS bundles
// that code-split into further lazy chunks and an i18n fetch, and only render
// once the live xml.cgi backend answers. Served by a honeypot — which has none
// of that — the genuine shell renders a blank page ("Loading chunk failed").
// So we keep the exact fingerprint head (title, favicon/logo refs) and the exact
// nginx header set, but give the body a real, deterministic login form (posting
// to xml.cgi?action=getauth, which the handler recognizes and captures). Nothing
// here is executed — it is static response data.

// danfossIndexHTML is the landing page served at "/": a self-contained login
// that visually replicates the live AK-SM "System Manager 800A" sign-in (its
// red Danfoss wordmark, title and version line, dark Sign In button on a
// #f0f0f0 background), captured from the rendered device. It references no
// external JS/CSS bundles, so it always renders; the form posts to
// xml.cgi?action=getauth, which the handler recognizes and captures. Measured
// styling (colors/sizes) is taken from the real page's computed styles.
const danfossIndexHTML = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Danfoss StoreView</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <link rel="icon" type="image/x-icon" href="favicon.ico">
  <link rel="shortcut icon" sizes="196x196" href="assets/images/logo.png">
  <style>
    html,body{height:100%;margin:0}
    body{font-family:sans-serif;background:#f0f0f0;color:#000;
      display:flex;flex-direction:column;align-items:center}
    .logo{margin-top:60px;text-align:center}
    .logo img{width:380px;max-width:92vw;height:auto}
    .title{color:#f00e0e;font-size:34px;font-weight:700;text-align:center;margin:40px 0}
    .version{font-size:16px;font-weight:700;text-align:center;margin:0 0 24px}
    .version small{color:#999;font-size:13px;font-weight:400}
    form{width:332px;max-width:92vw;text-align:center}
    input[type=text],input[type=password]{display:block;width:330px;max-width:92vw;box-sizing:border-box;
      height:40px;padding:6px 12px;margin:0 auto 8px;border:1px solid #c8c8c8;border-radius:3px;
      background:#fefefe;color:#000;font-size:14px}
    input::placeholder{color:#999}
    input[type=text]:focus,input[type=password]:focus{outline:none;border-color:#999}
    input[type=submit]{width:332px;max-width:92vw;margin-top:30px;padding:8px 16px;background:#323232;
      color:#fff;border:0;border-radius:4px;font-size:14px;font-weight:500;cursor:pointer}
    input[type=submit]:hover{background:#262626}
  </style>
</head>
<body class="simple-page">
  <div class="logo"><img src="assets/images/Danfoss-logo.png" alt="Danfoss-logo"></div>
  <div class="title">System Manager 800A</div>
  <h4 class="version">Version <small>SVB501.0.156</small></h4>
  <form action="xml.cgi?action=getauth" method="post" name="loginForm">
    <input id="user" type="text" name="user" placeholder="Username" autocomplete="username" spellcheck="false" autofocus>
    <input id="pwd" type="password" name="pwd" placeholder="Password" autocomplete="current-password">
    <input type="submit" value="Sign In">
  </form>
</body>
</html>
`

// danfossRespHeaders is the extra header block the live device emits on every
// response (an nginx config applied globally): the Server banner, the StoreView
// CORS policy — note the device-specific "aksm-auth" request header — and the
// no-store caching directive. svcHTTPResp adds Content-Type/Content-Length.
const danfossRespHeaders = "Server: nginx\r\n" +
	"Access-Control-Allow-Origin: *\r\n" +
	"Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n" +
	"Access-Control-Allow-Headers: aksm-auth,Keep-Alive,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type\r\n" +
	"Cache-Control: no-store, no-cache\r\n"

// Base64 of the device's real favicon.ico (16x16 image/x-icon),
// assets/images/logo.png (64x64 image/png) and the big red
// assets/images/Danfoss-logo.png wordmark (1280x527 image/png) shown on the
// login page. Decoded once at package load.
const danfossFaviconB64 = ""

const danfossLogoB64 = ""

const danfossWordmarkB64 = ""

// danfossFavicon, danfossLogo and danfossWordmark hold the decoded asset bytes
// (served verbatim).
var (
	danfossFavicon  = mustB64(danfossFaviconB64)
	danfossLogo     = mustB64(danfossLogoB64)
	danfossWordmark = mustB64(danfossWordmarkB64)
)

// mustB64 decodes an embedded, developer-supplied base64 asset at package load.
// The inputs are compile-time constants, so a decode error is a build-time bug.
func mustB64(s string) string {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic("danfoss asset: " + err.Error())
	}
	return string(b)
}
